fn solve(n: i8, m: i8) -> i8 {
    // First, form as many mixed groups as possible: each uses 1 from n and 2 from m.
    let mixed = n.min(m / 2);
    // Subtract the resource used by the mixed groups from m.
    let remaining_m = m - mixed * 2;
    // Then form pure groups from the remaining second resource: each uses 4 from m.
    let pure = remaining_m / 4;
    // Total groups is the sum of mixed and pure groups.
    mixed + pure
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_solve_examples() {
        // No resources → 0 groups
        assert_eq!(solve(0, 0), 0);
        // Only first resource, no second resource → 0 groups
        assert_eq!(solve(5, 0), 0);
        // Only second resource, can only form pure groups of 4
        assert_eq!(solve(0, 9), 2); // 9/4 = 2
        // Both resources, enough for mixed
        assert_eq!(solve(3, 10), 3 + 1); // Mixed = min(3,10/2)=3, rem=4 → pure=1
        // Limited by second resource
        assert_eq!(solve(10, 5), 2); // Mixed = min(10,5/2)=2, rem=1 → pure=0
        // Exactly fits mixed and pure
        assert_eq!(solve(4, 12), 4 + 1); // Mixed = min(4,12/2)=4, rem=4 → pure=1
    }
}